        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 44rem) {
        .app-shell {
          padding: 1rem;
        }

        .preview-header,
        .preview-actions {
          align-items: flex-start;
          flex-direction: column;
