<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --surface: #ffffff;
        --surface-muted: #f8fafc;
        --text: #111827;
        --muted: #64748b;
        --border: #e2e8f0;
        --danger: #dc2626;
        --danger-hover: #b91c1c;
        --primary: #2563eb;
        --shadow: 0 24px 70px rgba(15, 23, 42, 0.16);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.12), transparent 32rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      button {
        font: inherit;
      }

      .app-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem;
      }

      .preview-card {
        width: min(100%, 58rem);
        overflow: hidden;
        border: 1px solid rgba(226, 232, 240, 0.9);
        border-radius: 2rem;
        background: rgba(255, 255, 255, 0.88);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .preview-header,
      .preview-actions {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.25rem 1.5rem;
      }

      .eyebrow {
        margin: 0 0 0.25rem;
        color: var(--primary);
        font-size: 0.76rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.5rem, 3vw, 2.15rem);
        letter-spacing: -0.04em;
      }

      .image-meta {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .image-frame {
        margin: 0;
        padding: 0 1.5rem;
      }

      .image-frame img {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        border-radius: 1.35rem;
        object-fit: cover;
        box-shadow: 0 16px 40px rgba(15, 23, 42, 0.12);
      }

      figcaption {
        margin-top: 1rem;
        color: var(--muted);
        line-height: 1.6;
      }

      .preview-actions {
        margin-top: 0.5rem;
        border-top: 1px solid var(--border);
        background: var(--surface-muted);
      }

      .button {
        display: inline-flex;
        min-height: 2.75rem;
        align-items: center;
        justify-content: center;
        border: 0;
        border-radius: 999px;
        cursor: pointer;
        font-weight: 750;
        transition:
          transform 160ms ease,
          background-color 160ms ease,
          box-shadow 160ms ease;
      }

      .button:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.35);
        outline-offset: 3px;
      }

      .button:hover {
        transform: translateY(-1px);
      }

      .button-secondary {
        padding: 0 1.1rem;
        background: #e0e7ff;
        color: #1e3a8a;
      }

      .button-ghost {
        padding: 0 1.1rem;
        background: #eef2f7;
        color: #334155;
      }

      .button-danger {
        padding: 0 1.2rem;
        background: var(--danger);
        color: #ffffff;
        box-shadow: 0 12px 22px rgba(220, 38, 38, 0.24);
      }

      .button-danger:hover {
        background: var(--danger-hover);
      }

      .dialog-backdrop {
        position: fixed;
        inset: 0;
        display: none;
        place-items: center;
        padding: 1.25rem;
        background: rgba(15, 23, 42, 0.56);
        backdrop-filter: blur(10px);
      }

      .dialog-backdrop.is-open {
        display: grid;
      }

      .dialog {
        width: min(100%, 31rem);
        border: 1px solid rgba(255, 255, 255, 0.55);
        border-radius: 1.5rem;
        background: var(--surface);
        box-shadow: var(--shadow);
        transform: translateY(0);
      }

      .dialog-content {
        padding: 1.5rem;
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        margin-bottom: 1rem;
        place-items: center;
        border-radius: 999px;
        background: #fee2e2;
        color: var(--danger);
        font-size: 1.45rem;
        font-weight: 900;
      }

      .dialog h2 {
        margin: 0 0 0.55rem;
        font-size: 1.45rem;
        letter-spacing: -0.03em;
      }

      .dialog p {
        margin: 0;
        color: var(--muted);
        line-height: 1.65;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 44rem) {
        .app-shell {
          padding: 1rem;
        }

        .preview-header,
        .preview-actions {
          align-items: flex-start;
          flex-direction: column;
        }

        .preview-actions .button,
        .dialog-actions .button {
          width: 100%;
        }

        .image-frame {
          padding: 0 1rem;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script src="https://unpkg.com/react@18/umd/react.development.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script type="text/babel">
      const { forwardRef, useEffect, useRef, useState } = React;

      const Button = forwardRef(function Button(
        { children, className = "", variant = "secondary", ...props },
        ref
      ) {
        return (
          <button
            ref={ref}
            className={`button button-${variant} ${className}`.trim()}
            {...props}
          >
            {children}
          </button>
        );
      });

      function ImagePreview({ onDeleteClick }) {
        return (
          <main className="app-shell">
            <section className="preview-card" aria-labelledby="page-title">
              <header className="preview-header">
                <div>
                  <p className="eyebrow">Library preview</p>
                  <h1 id="page-title">Alpine Morning</h1>
                </div>
                <span className="image-meta">Saved May 5, 2026</span>
              </header>

              <figure className="image-frame">
                <img
                  src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
                  alt="Sunrise light over a quiet mountain lake surrounded by evergreen forest."
                />
                <figcaption>
                  A high-resolution landscape image stored in your personal library.
                </figcaption>
              </figure>

              <div className="preview-actions">
                <span className="image-meta">Image ID: IMG-2048</span>
                <Button className="trigger" variant="danger" onClick={onDeleteClick}>
                  Delete image
                </Button>
              </div>
            </section>
          </main>
        );
      }

      function ConfirmDeleteDialog({ isOpen, onClose }) {
        const dialogRef = useRef(null);
        const cancelRef = useRef(null);

        useEffect(() => {
          if (!isOpen) {
            return;
          }

          cancelRef.current?.focus();

          function handleKeyDown(event) {
            if (event.key === "Escape") {
              onClose();
            }
          }

          document.addEventListener("keydown", handleKeyDown);
          return () => document.removeEventListener("keydown", handleKeyDown);
        }, [isOpen, onClose]);

        function handleBackdropClick(event) {
          if (event.target === event.currentTarget) {
            onClose();
          }
        }

        return (
          <div
            className={`dialog-backdrop${isOpen ? " is-open" : ""}`}
            onMouseDown={handleBackdropClick}
            aria-hidden={!isOpen}
          >
            <section
              ref={dialogRef}
              className="dialog"
              role="dialog"
              aria-modal="true"
              aria-labelledby="dialog-title"
              aria-describedby="dialog-description"
            >
              <div className="dialog-content">
                <div className="dialog-icon" aria-hidden="true">
                  !
                </div>
                <h2 id="dialog-title">Delete this image?</h2>
                <p id="dialog-description">
                  This will permanently remove "Alpine Morning" from your library. This
                  action cannot be undone.
                </p>
                <div className="dialog-actions">
                  <Button ref={cancelRef} variant="ghost" onClick={onClose}>
                    Cancel
                  </Button>
                  <Button variant="danger" onClick={onClose}>
                    Confirm delete
                  </Button>
                </div>
              </div>
            </section>
          </div>
        );
      }

      function App() {
        const [isDialogOpen, setIsDialogOpen] = useState(false);

        return (
          <>
            <ImagePreview onDeleteClick={() => setIsDialogOpen(true)} />
            <ConfirmDeleteDialog
              isOpen={isDialogOpen}
              onClose={() => setIsDialogOpen(false)}
            />
          </>
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(<App />);
    </script>
  </body>
</html>
